// PATTERN 1: OPPOSITE ENDS — Two Sum on sorted array
// Naive: O(n²) nested loops checking every pair
// Two Pointer: O(n) time, O(1) space
function twoSumSorted(nums, target) {
    let left = 0, right = nums.length - 1;
    while (left < right) {
        const sum = nums[left] + nums[right];
        if (sum === target) return [left, right];  // found
        if (sum < target) left++;   // sum too small → move left right
        else right--;               // sum too big  → move right left
    }
    return [];
}
// Correctness proof:
// If sum < target: nums[left] is too small with ANY right partner.
//   Moving left forward is safe — we will never miss the answer.
// If sum > target: nums[right] is too large with ANY left partner.
//   Moving right backward is safe — we will never miss the answer.

// PATTERN 2: OPPOSITE ENDS — Valid Palindrome
function isPalindrome(s) {
    s = s.toLowerCase().replace(/[^a-z0-9]/g, '');
    let left = 0, right = s.length - 1;
    while (left < right) {
        if (s[left] !== s[right]) return false;
        left++;
        right--;
    }
    return true;
}
// Time: O(n)  Space: O(n) for cleaned string
// Space O(1) optimisation: skip non-alphanumeric in-place (no new string)

// PATTERN 3: SAME DIRECTION — Remove Duplicates In-Place (sorted array)
// slow pointer: next position to write a unique element
// fast pointer: scanning ahead for the next unique element
function removeDuplicatesSorted(nums) {
    if (nums.length === 0) return 0;
    let slow = 0;
    for (let fast = 1; fast < nums.length; fast++) {
        if (nums[fast] !== nums[slow]) {
            slow++;
            nums[slow] = nums[fast]; // write next unique value
        }
        // if equal: fast advances, slow stays — duplicate skipped
    }
    return slow + 1; // length of unique prefix
}
// [0,0,1,1,1,2,2,3]: result is [0,1,2,3,...] with count = 4
// Time: O(n)  Space: O(1)

