class RangeQueryEngine {
  constructor(arr) {
    this.prefix = new Array(arr.length + 1).fill(0);
    for (let i = 0; i < arr.length; i++) {
      this.prefix[i + 1] = this.prefix[i] + arr[i];
    }
  }
  query(l, r) {
    return this.prefix[r + 1] - this.prefix[l];
  }
}

function countSubarraysWithSum(nums, k) {
  const countMap = new Map([[0, 1]]);
  let prefixSum = 0;
  let count = 0;
  for (const num of nums) {
    prefixSum += num;
    count += countMap.get(prefixSum - k) || 0;
    countMap.set(prefixSum, (countMap.get(prefixSum) || 0) + 1);
  }
  return count;
}

