// VALID ANAGRAM: O(n) time, O(1) space (fixed 26-element alphabet)
function isAnagram(s, t) {
    if (s.length !== t.length) return false;
    const count = new Array(26).fill(0);
    for (let i = 0; i < s.length; i++) {
        count[s.charCodeAt(i) - 97]++; // increment for s
        count[t.charCodeAt(i) - 97]--; // decrement for t
    }
    return count.every(c => c === 0); // all zeros = same frequencies
}
// 'anagram' vs 'nagaram' → all frequencies cancel → true
// 'rat' vs 'car' → count[r-97] = +1 not cancelled → false

// GROUP ANAGRAMS: O(n × k log k) where k = average string length
function groupAnagrams(strs) {
    const map = new Map();
    for (const s of strs) {
        const key = s.split('').sort().join(''); // sorted string as key
        if (!map.has(key)) map.set(key, []);
        map.get(key).push(s);
    }
    return [...map.values()];
}
// ['eat','tea','tan','ate','nat','bat']
// 'eat'→'aet', 'tea'→'aet', 'ate'→'aet' → same group
// 'tan'→'ant', 'nat'→'ant' → same group
// 'bat'→'abt' → own group

// FIND ALL ANAGRAMS IN STRING: Sliding Window + Frequency Map O(n)
function findAnagrams(s, p) {
    if (s.length < p.length) return [];
    const pCount = new Array(26).fill(0);
    const wCount = new Array(26).fill(0);
    for (let i = 0; i < p.length; i++) {
        pCount[p.charCodeAt(i) - 97]++;
        wCount[s.charCodeAt(i) - 97]++;
    }
    const result = [];
    if (pCount.join() === wCount.join()) result.push(0);

    for (let right = p.length; right < s.length; right++) {
        wCount[s.charCodeAt(right) - 97]++;                  // add new right char
        wCount[s.charCodeAt(right - p.length) - 97]--;      // remove old left char
        if (pCount.join() === wCount.join()) result.push(right - p.length + 1);
    }
    return result;
}
// s='cbaebabacd', p='abc' → result=[0,6]
// Time: O(n)  Space: O(1) — fixed 26-element arrays

