  return maxSum;
}

function maxProductSubarray(nums) {
  let maxProd = nums[0], minProd = nums[0], result = nums[0];
  for (let i = 1; i < nums.length; i++) {
    const num = nums[i];
    const candidates = [num, maxProd * num, minProd * num];
    maxProd = Math.max(...candidates);
    minProd = Math.min(...candidates);
    result = Math.max(result, maxProd);
  }
  return result;
}

function minSubArrayLen(target, nums) {
  let left = 0, sum = 0, minLen = Infinity;
  for (let right = 0; right < nums.length; right++) {
    sum += nums[right];
    while (sum >= target) {
      minLen = Math.min(minLen, right - left + 1);
      sum -= nums[left];
      left++;
    }
  }
  return minLen === Infinity ? 0 : minLen;
}

function selectPattern(descriptor) {
  const map = {
    max_sum: 'Kadane',
    max_product: 'Kadane variant (min tracking)',
    min_size_sum_positive: 'Sliding Window'
  };
  return map[descriptor];
}

