// PATTERN SELECTION CHEAT SHEET — apply this to every new problem

// Signal: 'sorted array' + 'pair' + 'target sum/difference'  → TWO POINTERS
// Signal: 'palindrome' or 'symmetry'                          → TWO POINTERS
// Signal: 'remove duplicates in-place from sorted array'      → TWO POINTERS (slow/fast)

// Signal: 'subarray of exactly size k' + 'max/min/sum'        → FIXED SLIDING WINDOW
// Signal: 'longest/shortest contiguous' + 'constraint'        → VARIABLE SLIDING WINDOW

// Signal: 'range sum query' on static array                   → PREFIX SUM
// Signal: 'count subarrays with sum = k' (any integers)       → PREFIX SUM + HASHMAP

// Signal: 'anagram' or 'permutation' in string                → CHARACTER MAP + SLIDING WINDOW
// Signal: 'valid anagram' of two strings                      → CHARACTER MAP

// Signal: 'maximum subarray sum' (negatives allowed)          → KADANE'S
// Signal: 'maximum product subarray'                          → KADANE'S VARIANT (track min too)

// EXAMPLE: Apply the decision tree
// Problem: 'Longest subarray with at most k zeros'
// Signal: 'longest' + 'contiguous subarray' + 'at most k' → VARIABLE SLIDING WINDOW
function longestSubarrayKZeros(nums, k) {
    let left = 0, zeros = 0, maxLen = 0;
    for (let right = 0; right < nums.length; right++) {
        if (nums[right] === 0) zeros++;
        while (zeros > k) { if (nums[left++] === 0) zeros--; }
        maxLen = Math.max(maxLen, right - left + 1);
    }
    return maxLen;
}

