function maxProfit(prices) {
    let minPrice = prices[0];
    let maxProfit = 0;
    for (let i = 1; i < prices.length; i++) {
        minPrice = Math.min(minPrice, prices[i]);  // best buy price up to today
        maxProfit = Math.max(maxProfit, prices[i] - minPrice); // best profit if sell today
    }
    return maxProfit;
}

