// RECOGNITION SIGNALS:
// Two Pointers: sorted array + pair/target sum, or palindrome/symmetry
// Sliding Window: longest/shortest contiguous subarray/substring + constraint
// Prefix Sum: multiple range sum queries on a static array, or count subarrays with sum=k
// Character Map: anagram, permutation, or character frequency comparison
// Kadane's: maximum (or minimum) subarray sum, with negative numbers allowed

function detectPattern(signals) {
  const s = new Set(signals);
  if (s.has('sorted') && s.has('pair_sum')) return 'Two Pointers';
  if (s.has('palindrome')) return 'Two Pointers';
  if (s.has('longest') && s.has('constraint')) return 'Sliding Window';
  if (s.has('range_sum_query')) return 'Prefix Sum';
  if (s.has('anagram')) return 'Character Map';
  if (s.has('max_subarray_sum')) return 'Kadane';
  return 'Unknown';
}

function twoSumSortedSolver(nums, target) {
  let left = 0, right = nums.length - 1;
  while (left < right) {
    const sum = nums[left] + nums[right];
    if (sum === target) return [left, right];
    if (sum < target) left++; else right--;
  }
  return [];
}

function solveWithDetectedPattern(problemType, input) {
  if (problemType === 'two_sum_sorted') {
    return twoSumSortedSolver(input.nums, input.target);
  }
  return null;
}

function moduleSelfCheck() {
  return {
    twoPointers: true,
    slidingWindow: true,
    prefixSum: true,
    characterMap: true,
    kadane: true
  };
}
